def transform(grid):
    cells={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==8}
    pieces=[]
    h,w=len(grid),len(grid[0])
    for r in range(h-1):
        for c in range(w-1):
            box={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
            if box<=cells: pieces.append((box,1))
            for miss in box:
                shape=box-{miss}
                if shape<=cells:
                    color={(r,c):2,(r,c+1):4,(r+1,c):3,(r+1,c+1):2}[miss]
                    pieces.append((shape,color))
    def solve(rem, chosen):
        if not rem: return chosen
        x=min(rem)
        for shape,color in pieces:
            if x in shape and shape<=rem:
                ans=solve(rem-shape,chosen+[(shape,color)])
                if ans is not None:return ans
        return None
    chosen=solve(cells,[])
    out=[[0]*w for _ in range(h)]
    for shape,color in chosen:
        for r,c in shape: out[r][c]=color
    return out
